select id, title, material_type, length(content) as len, (content ~* '<img') as has_img, (content ~* '<svg') as has_svg, (content ~* '<figure') as has_figure, (content ~* 'src=') as has_src, substring(content from '(?i)<img[^>]*>') as first_img, substring(content from '(?i)src="[^"]*"') as first_src from public.study_materials where title ilike '%graph%' or content ilike '%Algebra — Graphs%' or content ~* '<img|<svg|<figure' order by title limit 40;
